"""Render deploy/nginx/spa_headers.conf from the application's own CSP (single source of truth).

    PUBLIC_BASE_URL=https://bastion.example python scripts/render_nginx.py
"""
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))
os.environ.setdefault("ENV", "development")

from app.middleware import frontend_csp  # noqa: E402

out = ROOT / "deploy" / "nginx" / "spa_headers.conf"
csp = frontend_csp()
if '"' in csp:
    raise SystemExit("CSP must not contain double quotes")
out.write_text(
    "# GENERATED by scripts/render_nginx.py from app.middleware.frontend_csp(). Do not edit.\n"
    "include /etc/nginx/snippets/security_headers.conf;\n"
    f'add_header Content-Security-Policy "{csp}" always;\n'
)
print(f"wrote {out.relative_to(ROOT)} for {os.environ.get('PUBLIC_BASE_URL')}")
